const input = $input.first().json;

if (!Array.isArray(input)) {
  console.log('⚠️ Нет данных от Supabase');
  return { json: { skip: true, reason: 'no_data' } };
}

const posts = input;
console.log(`📊 Получено постов за период 1-22 января: ${posts.length}`);

if (posts.length === 0) {
  return { json: { skip: true, reason: 'no_posts' } };
}

// Считаем метрики
const stories = posts.filter(p => {
  const mediaType = (p.media_type || '').toLowerCase();
  return mediaType.includes('story') || mediaType === 'stories';
}).length;

const publications = posts.filter(p => {
  const mediaType = (p.media_type || '').toLowerCase();
  return !mediaType.includes('story') && mediaType !== 'stories';
}).length;

// Суммируем метрики
const totalReach = posts.reduce((sum, p) => sum + (p.reach || 0), 0);
const totalImpressions = posts.reduce((sum, p) => sum + (p.impressions || 0), 0);
const totalLikes = posts.reduce((sum, p) => sum + (p.likes || 0), 0);
const totalComments = posts.reduce((sum, p) => sum + (p.comments || 0), 0);
const totalShares = posts.reduce((sum, p) => sum + (p.shares || 0), 0);

// Вовлеченность = (лайки + комментарии + репосты) / показы * 100
const engagement = totalImpressions > 0 
  ? ((totalLikes + totalComments + totalShares) / totalImpressions) * 100 
  : 0;

// Бизнес-метрики
const totalDiagnostics = posts.reduce((sum, p) => sum + (p.leads_count || 0), 0);
const totalSales = posts.reduce((sum, p) => sum + (p.paid_leads || 0), 0);
const totalRevenue = posts.reduce((sum, p) => sum + (p.revenue || 0), 0);

const projectId = '64c94e87-630c-470e-8ab1-8f7c8c835efa';

const result = {
  project_id: projectId,
  period_start: '2026-01-01',
  period_end: '2026-01-22',
  publications: publications,
  stories: stories,
  reach: totalReach,
  engagement: Math.round(engagement * 100) / 100, // 2 знака после запятой
  followers: 0, // TODO: получить из Instagram Insights API
  diagnostics: totalDiagnostics,
  sales: totalSales,
  revenue: Math.round(totalRevenue), // БЕЗ КОПЕЕК
};

console.log(`\n✅ Агрегированные метрики за 1-22 января:`);
console.log(`   Публикации: ${publications}`);
console.log(`   Сторис: ${stories}`);
console.log(`   Охват: ${totalReach.toLocaleString('ru-RU')}`);
console.log(`   Вовлеченность: ${result.engagement}%`);
console.log(`   Диагностики: ${totalDiagnostics}`);
console.log(`   Продажи: ${totalSales}`);
console.log(`   Выручка: ${totalRevenue.toLocaleString('ru-RU')}₸`);

return { json: result };

